import { Component, Injector, OnInit, ViewChild } from '@angular/core';
import { CardPrincipal } from 'src/app/models/card-principal.model';
import { GenericResult } from 'src/app/models/generic-result.model';
import { PexelsPhoto } from 'src/app/models/pexels/pexels-photo.model';
import { PexelsResponse } from 'src/app/models/pexels/pexels-response.model';
import { CardService } from 'src/app/services/card/card.service';
import { ImagesService } from 'src/app/services/external/images/images.service';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.css']
})
export class HomeComponent implements OnInit{
  
  public cardPrincipal: CardPrincipal[] = [];
  public showComments: boolean = false;
  public currentTitle: string = '';
  public currentDescription: string = '';
  
  constructor(private cardService: CardService,
    private imageteste: ImagesService) {
    }

  ngOnInit() {
    this.loadCards();
    // console.log('card principal ', this.cardPrincipal)
  }

  public showCommentsOnClick(): void {
    this.showComments = true;
    console.log('sendo chamado', this.showComments)
  }

  loadCards() {
    this.cardService.getCards()
    .subscribe(
      {
        next: (response: GenericResult) => {
          if (Array.isArray(response.data)) {
            this.cardPrincipal = response.data;
            console.log('imagens ', response)
          } else {
            this.cardPrincipal.push(response.data);
          }
        },
        error: (err) => {
          console.log(err)
        }
      }
    )
  }

  showCardDetails(title: string, description: string): void{
    this.currentTitle = title;
    this.currentDescription = description;
  }

  // addNewCard() {
  //   console.log("funcionando")
  // }

  // getHappyImage() {
  //   return this.sort(this.happyImage.photos);
  // }

  // sort(photos: PexelsPhoto[]) {
  //   // return photos[0].src.medium;
  //   return null;
  // }
}
<div>
  <app-navbar></app-navbar>
</div>

<div class="default-body">
  <div class="uk-container">
    <nav class="uk-navbar-container-default" uk-navbar>
      <div class="uk-navbar-left">
        <ul class="uk-navbar-nav">
          <li class="uk-active">Solidariedade Anonima</li>
        </ul>
      </div>
      <div class="uk-navbar-right">
        <ul class="uk-navbar-nav">
          <li class="uk-active">
            <a href="#modal-sections" uk-toggle>
              <span class="uk-icon uk-margin-small-right" uk-icon="icon: plus"></span>
              Adicionar
              <app-add-card-modal></app-add-card-modal>
            </a>
          </li>
        </ul>
      </div>
    </nav>
  </div>


  <div class="uk-container">
    
    <div uk-grid>
      <div class="uk-width-2-4" *ngFor="let card of cardPrincipal">
        <div class="uk-card uk-card-default uk-grid-collapse uk-child-width-1-2@s uk-margin" uk-grid>

          <div class="uk-card-media-left uk-cover-container">
              <img [src]="card.imageLarge" alt="" uk-cover>
              <canvas width="600" height="400"></canvas>
          </div>
    
          <div class="body-card-style">
              <div class="uk-card-body" style="text-align: center;">
                  <h3 class="uk-card-title card-title">{{ card.title }}</h3>
              </div>
    
              <div class="body-button-div">
                <a class="uk-button uk-button-default body-button-style" href="#modal-full" uk-toggle (click)="showCardDetails(card.title, card.description)">
                  <span class="uk-icon uk-margin-small-right" uk-icon="icon: pencil"></span>
                  Visualizar
                </a>
                <show-card-modal
                [comments]="showComments"
                [title]="currentTitle"
                [description]="currentDescription">
                </show-card-modal>
              </div>
          </div>         
        </div>
      </div>
    </div>
  </div>
</div>
